"""Snap span edges to a fixed step and label the result."""

from typing import Iterable, List

from hourglass.parsing import format_clock
from hourglass.models import Span

def check_step(step: int) -> None:
    if step <= 0 or 60 % step != 0:
        raise ValueError(f"bad step: {step!r}")

def snap(minutes: int, step: int) -> int:
    """Nearest multiple of step, with halves going up."""
    return (2 * minutes + step) // (2 * step) * step

def duration_text(minutes: int) -> str:
    hours, remainder = divmod(minutes, 60)
    return f"{hours}h {remainder}m"

def round_span(span: Span, step: int) -> Span:
    """Snap both edges. Raises if the span collapses."""
    start = snap(span.start, step)
    return Span(start, snap(span.end, step))

def label_span(span: Span) -> str:
    first = format_clock(span.start)
    last = format_clock(span.end)
    length = duration_text(span.minutes)
    return f"{first}-{last} ({length})"

# ---
def round_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels such as 09:00-17:15 (8h 15m), one per span."""
    check_step(step)
    rounded = [round_span(item, step) for item in spans]
    return [label_span(item) for item in rounded]

