import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span

class RoundLabelTests(unittest.TestCase):
    # ---
    def test_snaps_to_nearest_step(self):
        spans = [Span(543, 1031)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    # ---
    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(125, 245)]
        self.assertEqual(
            round_labels(spans, 5),
            ["01:00-02:00 (1h 0m)", "02:05-04:05 (2h 0m)"]
        )

    # ---
    def test_halves_round_up(self):
        spans = [Span(0, 25)]
        self.assertEqual(
            round_labels(spans, 10),
            ["00:00-00:30 (0h 30m)"]
        )

    # ---
    def test_empty_input(self):
        self.assertEqual(round_labels([], 15), [])

    # ---
    def test_end_of_day(self):
        spans = [Span(1400, 1440)]
        self.assertEqual(
            round_labels(spans, 30),
            ["23:30-24:00 (0h 30m)"]
        )

    # ---
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)

    # ---
    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_labels([Span(61, 64)], 15)

if __name__ == "__main__":
    unittest.main()
